Date leap = Date.newInstance(2024, 1, 31);
System.assertEquals('2024-02-29', leap.addMonths(1).format());
System.assertEquals('2023-12-31', leap.addMonths(-1).format());
Date leapDay = Date.newInstance(2024, 2, 29);
System.assertEquals('2025-02-28', leapDay.addYears(1).format());
System.assertEquals('2023-02-28', leapDay.addYears(-1).format());
System.assertEquals('2026-05-02', Date.today().format());
Datetime stamp = Datetime.newInstanceGmt(2024, 2, 29, 23, 58, 59);
System.assertEquals('2024-03-01T23:58:59Z', stamp.addDays(1).formatGmt());
System.assertEquals('2024-01-29T23:58:59Z', stamp.addMonths(-1).formatGmt());
System.assertEquals('2025-02-28T23:58:59Z', stamp.addYears(1).formatGmt());
System.assertEquals('2023-02-28T23:58:59Z', stamp.addYears(-1).formatGmt());
System.assertEquals('2026-05-02T12:00:00Z', Datetime.now().formatGmt());
System.assertEquals('2024-02-29 23:58:59.000 +0000 UTC', stamp.formatGmt('yyyy-MM-dd HH:mm:ss.SSS Z z'));
Datetime summer = Datetime.valueOfGmt('2024-07-01T12:00:00Z');
System.assertEquals('2024-07-01 08:00:00 -0400 EDT', summer.format('yyyy-MM-dd HH:mm:ss Z z', 'America/New_York'));
TimeZone fixed = TimeZone.getTimeZone('UTC-02:00');
System.assertEquals('GMT-02:00', fixed.getID());
System.assertEquals('GMT-02:00', fixed.getDisplayName());
System.assertEquals(-7200000, fixed.getOffset(stamp));
TimeZone berlin = TimeZone.getTimeZone('Europe/Berlin');
System.assertEquals('Europe/Berlin', berlin.getID());
System.assertEquals('Europe/Berlin', berlin.getDisplayName());
System.assertEquals('CET', berlin.getDisplayName(false));
System.assertEquals('CEST', berlin.getDisplayName(true));
System.assertEquals(7200000, berlin.getOffset(summer));

